package com.example.riskplatform.service;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.example.riskplatform.common.BusinessException;import com.example.riskplatform.dto.Requests.MetricRequest;import com.example.riskplatform.entity.Metric;import com.example.riskplatform.mapper.MetricMapper;import com.example.riskplatform.service.mq.RiskTaskDispatcher;import lombok.RequiredArgsConstructor;import com.example.riskplatform.service.rag.CorpusEvents;import org.springframework.beans.BeanUtils;import org.springframework.stereotype.Service;import java.time.LocalDate;import java.util.*;
@Service @RequiredArgsConstructor public class MetricService{private final MetricMapper mapper;private final DataScopeService scope;private final RiskTaskDispatcher dispatcher;private final AuditService audit;private final CorpusEvents corpus;public List<Metric>list(Long cid,String code,LocalDate start,LocalDate end){LambdaQueryWrapper<Metric>w=new LambdaQueryWrapper<>();List<Long>ids=scope.allowedCompanyIds();if(cid!=null){if(!scope.canAccess(cid))throw new BusinessException(403,"无权访问");w.eq(Metric::getCompanyId,cid);}else if(ids!=null){if(ids.isEmpty())return List.of();w.in(Metric::getCompanyId,ids);}if(code!=null&&!code.isBlank())w.eq(Metric::getMetricCode,code);if(start!=null)w.ge(Metric::getMetricDate,start);if(end!=null)w.le(Metric::getMetricDate,end);return mapper.selectList(w.orderByDesc(Metric::getMetricDate).last("LIMIT 500"));}public Metric create(MetricRequest r){if(!scope.canAccess(r.getCompanyId()))throw new BusinessException(403,"无权录入该企业指标");Metric m=new Metric();BeanUtils.copyProperties(r,m);mapper.insert(m);corpus.upsert("metric",m.getId(),m.getCompanyId());corpus.aggregate(m.getCompanyId());audit.log("CREATE","METRIC",m.getId(),m.getMetricCode()+"="+m.getMetricValue());dispatcher.dispatch(m.getId());return m;}}
